"""Serve maintainer-fixed engineering probes in the existing bounded sandbox."""

import json
from pathlib import Path
import sys

from probe import run

TRACE_LIMIT = 256
TRACE_ENVELOPE = 16 * 1024


def traced_response(result, files, source):
    if result["exitCode"] != 0 or result["truncated"] or result["stderr"]:
        return {"status": "unavailable"}
    try:
        row = json.loads(result["stdout"])
        if row.keys() != {"exitCode", "stdout", "stderr", "truncated", "executed"}:
            raise ValueError("Invalid trace frame")
        if type(row["exitCode"]) is not int or not 0 <= row["exitCode"] <= 255 or row["truncated"] is not False:
            raise ValueError("Invalid trace outcome")
        if any(type(row[key]) is not str or len(row[key].encode("utf-8")) > 2048 for key in ("stdout", "stderr")):
            raise ValueError("Invalid candidate stream")
        executed = row["executed"]
        if type(executed) is not list or not 1 <= len(executed) <= TRACE_LIMIT:
            raise ValueError("Missing or oversized trace")
        limits = {path:len((source / path).read_bytes().splitlines()) for path in files}
        sites = set()
        for item in executed:
            path, line = item.get("path"), item.get("line")
            if (item.keys() != {"path", "line"} or path not in limits or type(line) is not int or
                    not 1 <= line <= limits[path] or (path,line) in sites):
                raise ValueError("Unexpected trace location")
            sites.add((path,line))
    except (AttributeError, KeyError, TypeError, ValueError):
        return {"status": "unavailable"}
    return row


def main():
    source, helper, trace_helper = map(Path, sys.argv[1:4])
    entry, *files = sys.argv[4:]
    request = json.load(sys.stdin)
    target = request["target"]
    traced = request.get("trace") is True
    recipe = {
        "executable": "/usr/bin/python3",
        "fixedArgs": ["-E", "-s", "-B"],
        "mounts": [{"source": "/usr", "target": "/usr"}],
        "links": [{"source": "/usr/lib", "target": "/lib"}, {"source": "/usr/lib64", "target": "/lib64"}],
        "maxArgs": 0,
        "allowStdin": target is None,
        "timeoutMs": 3000,
    }
    if target is None and traced:
        if entry not in files or any(not (source / name).is_file() for name in files):
            return 2
        recipe["mounts"].append({"source": str(trace_helper), "target": "/trusted-trace.py"})
        recipe["fixedArgs"] += ["/trusted-trace.py", entry, *files]
    elif target is None:
        recipe["entrypoint"] = entry
    else:
        recipe["mounts"].append({"source": str(helper), "target": "/trusted-syntax.py"})
        recipe["fixedArgs"] += ["/trusted-syntax.py", target]
    inputs = {"stdin": request["stdin"]} if "stdin" in request else {}
    result = run(recipe, source, inputs, preview=TRACE_ENVELOPE) if traced else run(recipe, source, inputs)
    if result.get("status") == "timeout":
        print(json.dumps({"status": "unavailable" if traced else "execution-timeout"}))
        return 0
    if result.get("status") != "exited":
        return 2
    response = traced_response(result, files, source) if traced else {
        key: result[key] for key in ("exitCode", "stdout", "stderr", "truncated", "stack") if key in result}
    print(json.dumps(response, ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())

