"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Kahn's algorithm, lexicographic ID tie-breaking among eligible nodes."""
    known = {change["id"] for change in changes}
    pending = {change["id"]: len(change["depends_on"]) for change in changes}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        for target in change["depends_on"]:
            if target not in known:
                raise JournalError("unknown-dependency")
            dependents[target].append(change["id"])
    eligible = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        change_id = heapq.heappop(eligible)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(eligible, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        _, action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []), {row["id"] for row in changes})
        order = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_of = {change["id"]: change["units"] for change in changes}
    if action == "rollback":
        actions = [change_id for change_id in reversed(order) if change_id in applied]
        return {"status": "ok", "actions": actions, "units": sum(units_of[i] for i in actions)}
    actions = [change_id for change_id in order if change_id not in applied]
    units = sum(units_of[change_id] for change_id in actions)
    if units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

policy.py.text:
"""Validate release policy before computing actions."""

ENVIRONMENTS = ("staging", "production")
SUPPORTED_BY_ENVIRONMENT = {
    "staging": ("plan", "rollback"),
    "production": ("plan", "rollback"),
}


class PolicyError(ValueError):
    pass


def action_for(request, environment):
    action = request.get("action")
    if not isinstance(action, str) or action not in SUPPORTED_BY_ENVIRONMENT[environment]:
        raise PolicyError("unsupported-action")
    return action


def limit_for(request):
    environment = request.get("environment")
    if not isinstance(environment, str) or environment not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")
    action = action_for(request, environment)
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return environment, action, budget

