"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _text(value):
    return isinstance(value, str) and value != ""


def _id_list(value, code="invalid-change"):
    if not isinstance(value, list):
        raise JournalError(code)
    if not all(_text(item) for item in value):
        raise JournalError(code)
    return frozenset(value)


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict)
                or not _text(row.get("id"))
                or not _text(row.get("component"))
                or type(row.get("units")) is not int
                or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _id_list(row.get("depends_on", [])),
        }
        previous = changes.get(change["id"])
        if previous is not None:
            if previous != change:
                raise JournalError("conflicting-change")
            continue
        changes[change["id"]] = change
    return sorted(changes.values(), key=lambda change: change["id"])


def read_applied(ids, known):
    applied = _id_list(ids)
    if not applied <= known:
        raise JournalError("unknown-dependency")
    return applied


def read_retain(ids, applied):
    """G2: rollback retention is a list of IDs that are already applied."""
    retain = _id_list(ids, "invalid-retain")
    if not retain <= applied:
        raise JournalError("invalid-retain")
    return retain

