journal.py.text:
"""Normalize release records at the input boundary: validation, identity, replay.

This module is the only place that looks at raw request fields for changes,
dependencies and the persisted ``applied`` journal. Both plan and rollback in
planner.py therefore share one validation verdict, so an invalid request can
never be accepted on one path and rejected on the other. Validation is
graph-side only: it never consults ``environment``, which keeps policy
concerns in policy.py and avoids order coupling.
"""
import heapq


class JournalError(ValueError):
    """Carries the single error code for a rejected request."""

    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _id_list(container, field):
    """Validate an optional array of change-ID strings held under ``field``.

    Only an absent key means "field omitted" and maps to the default empty
    array. An explicit ``null`` is present but not an array, so it is
    malformed input (``invalid-change``) just like any other non-array; a
    non-array, or any element that is not a nonempty string, collapses to the
    same single code so the wire contract exposes no per-element detail.
    """
    value = container.get(field, [])
    if value is None:
        return []
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
    return list(value)


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        changes.append({
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _id_list(row, "depends_on"),
        })
    return changes


def read_applied(request):
    """Return the caller-supplied persisted release journal IDs (default empty when omitted)."""
    return _id_list(request, "applied")


def canonical(changes):
    """Collapse identical duplicates and reject conflicting IDs, preserving input order.

    Equality covers id, component, units and the *set* of dependencies, so the
    same record listed twice with reordered ``depends_on`` is one change.
    Deduplication must happen before accounting and graph construction,
    otherwise duplicates would double-count units and add parallel edges.
    """
    seen = {}
    unique = []
    for row in changes:
        key = (row["id"], row["component"], row["units"], frozenset(row["depends_on"]))
        previous = seen.get(row["id"])
        if previous is None:
            seen[row["id"]] = key
            unique.append(row)
        elif previous != key:
            raise JournalError("conflicting-change")
    return unique


def check_references(unique, applied):
    """Reject dangling edges before ordering; return the applied-ID set.

    A missing dependency target, or an applied ID with no change record, means
    the caller and the persisted journal disagree about the graph, so both
    fail with ``unknown-dependency`` rather than emit a plan that cannot be
    executed. ``applied`` may restate an ID, hence a set.
    """
    known = {row["id"] for row in unique}
    for row in unique:
        for target in row["depends_on"]:
            if target not in known:
                raise JournalError("unknown-dependency")
    for change_id in applied:
        if change_id not in known:
            raise JournalError("unknown-dependency")
    return set(applied)


def dependents_graph(unique):
    """Build ``dependents[id]`` and ``pending[id]`` = number of unmet prerequisites.

    The graph is over deduplicated records only; edges are deduplicated per
    pair so a repeated dependency name cannot inflate an in-degree.
    """
    dependents = {row["id"]: [] for row in unique}
    pending = {}
    for row in unique:
        targets = set(row["depends_on"])
        pending[row["id"]] = len(targets)
        for target in targets:
            dependents[target].append(row["id"])
    return dependents, pending


def topological_order(dependents, pending):
    """Deterministic topological order, ties broken by lexicographically smallest ID.

    Kahn's algorithm over a heap-backed ready set: the result is a pure
    function of the deduplicated graph, independent of input order, so plan and
    rollback observe the same full order. A nonempty remainder means a cycle
    anywhere in the graph, including components unreachable from the roots.
    """
    remaining = dict(pending)
    ready = [change_id for change_id, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for nxt in dependents[current]:
            remaining[nxt] -= 1
            if remaining[nxt] == 0:
                heapq.heappush(ready, nxt)
    if len(order) != len(remaining):
        raise JournalError("dependency-cycle")
    return order

planner.py.text:
"""Compose policy and journal data into a single result.

Import direction is fixed by SPEC: planner is the only module that knows both
policy (environment/budget) and journal (validation/identity/graph), and it owns
ordering plus result assembly. No other module assembles or emits a result, so
the exact success/failure shapes live here alone.
"""
from journal import (
    JournalError,
    canonical,
    check_references,
    dependents_graph,
    read_applied,
    read_changes,
    topological_order,
)
from policy import PolicyError, limit_for


def failure(code):
    """The single failure shape: no partial actions on any error path."""
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _emit(actions, units):
    return {"status": "ok", "actions": actions, "units": units}


def handle(request):
    """Dispatch one request object to plan or rollback."""
    if not isinstance(request, dict):
        # Protected interface: a non-object request stays invalid-request and
        # must not be reclassified by any later validation.
        return failure("invalid-request")
    try:
        # Policy runs first: SPEC layers transport (release.py) then policy,
        # so invalid-environment / unsupported-action / invalid-budget win over
        # any graph error and stay stable regardless of ``changes`` content.
        budget = limit_for(request)
        action = request.get("action")
        unique = canonical(read_changes(request.get("changes")))
        applied = check_references(unique, read_applied(request))
        order = topological_order(*dependents_graph(unique))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = {row["id"]: row["units"] for row in unique}
    if action == "rollback":
        return _rollback(order, applied, units)
    return _plan(order, applied, units, budget)


def _plan(order, applied, units, budget):
    """Emit unapplied changes in deterministic order if their total fits the budget.

    Already applied entries satisfy dependencies and are filtered out before
    accounting, so they never consume new budget. The budget is compared
    against the *emitted* sum after replay/deduplication and before anything
    is built, hence an excess emits no partial actions.
    """
    actions = [change_id for change_id in order if change_id not in applied]
    total = sum(units[change_id] for change_id in actions)
    if total > budget:
        return failure("budget-exceeded")
    return _emit(actions, total)


def _rollback(order, applied, units):
    """Emit applied changes in reverse of the full deterministic topological order.

    Reverse order guarantees a dependent is rolled back before its
    prerequisite. The budget was already validated by policy but deliberately
    does not cap rollback, because undoing an already released journal must
    not be blocked by a planning quota.
    """
    actions = [change_id for change_id in reversed(order) if change_id in applied]
    return _emit(actions, sum(units[change_id] for change_id in actions))


def plan(request):
    """Entry point used by release.py; kept as the module's public name."""
    return handle(request)

