    """Collapse identical duplicates and reject conflicting IDs, preserving input order.

    Equality covers id, component, units and the *set* of dependencies, so the
    same record listed twice with reordered ``depends_on`` is one change.
    Deduplication must happen before accounting and graph construction,
    otherwise duplicates would double-count units and add parallel edges.
    """
    seen = {}
    unique = []
    for row in changes:
        key = (row["id"], row["component"], row["units"], frozenset(row["depends_on"]))
        previous = seen.get(row["id"])
        if previous is None:
            seen[row["id"]] = key
            unique.append(row)
        elif previous != key:
            raise JournalError("conflicting-change")
    return unique


def check_references(unique, applied):
    """Reject dangling edges before ordering; return the applied-ID set.

    A missing dependency target, or an applied ID with no change record, means
    the caller and the persisted journal disagree about the graph, so both
    fail with ``unknown-dependency`` rather than emit a plan that cannot be
    executed. ``applied`` may restate an ID, hence a set.
    """
    known = {row["id"] for row in unique}
    for row in unique:
        for target in row["depends_on"]:
            if target not in known:
                raise JournalError("unknown-dependency")
    for change_id in applied:
        if change_id not in known:
            raise JournalError("unknown-dependency")
    return set(applied)


def dependents_graph(unique):
    """Build ``dependents[id]`` and ``pending[id]`` = number of unmet prerequisites.

    The graph is over deduplicated records only; edges are deduplicated per
    pair so a repeated dependency name cannot inflate an in-degree.
    """
    dependents = {row["id"]: [] for row in unique}
