def failure(code):
    """The single failure shape: no partial actions on any error path."""
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _emit(actions, units):
    return {"status": "ok", "actions": actions, "units": units}


def _retain_set(request, applied, dependencies):
    """Return the rollback retention closure: ``retain`` plus applied transitive dependencies.

    G2 adds ``retain`` to staging rollback only, so the field is read here and
    nowhere else: a plan request carrying ``retain`` is ignored rather than
    rejected, which keeps G1 plan requests valid unchanged.

    Every retain entry must be a nonempty string naming an *applied* change.
    Non-array, non-string or unknown/nonapplied IDs all collapse to
    ``invalid-retain`` so the wire contract exposes no per-element detail.

    The closure walks ``depends_on`` from the retained IDs and keeps only
    applied prerequisites: an applied prerequisite cannot be rolled back while
    an applied dependent that must remain is still in place, and an unapplied
    prerequisite has nothing to retain. Callers must have already validated
    references, so every target exists in ``dependencies``.
    """
    value = request.get("retain", [])
    if not isinstance(value, list):
        raise JournalError("invalid-retain")
    keep = set()
    pending = []
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-retain")
        if item not in applied:
            # Rejected, not silently dropped: retaining a change the journal
            # never recorded is a caller bug and must not be guessed at.
            raise JournalError("invalid-retain")
        pending.append(item)
    while pending:
        current = pending.pop()
        if current in keep:
            continue
        keep.add(current)
        for target in dependencies[current]:
            if target in applied and target not in keep:
                pending.append(target)
    return keep


def handle(request):
    """Dispatch one request object to plan or rollback."""
    if not isinstance(request, dict):
        # Protected interface: a non-object request stays invalid-request and
        # must not be reclassified by any later validation.
        return failure("invalid-request")
    try:
        # Policy runs first: SPEC layers transport (release.py) then policy,
        # so invalid-environment / unsupported-action / invalid-budget win over
        # any graph error and stay stable regardless of ``changes`` content.
        budget = plan_budget(request)
        action = request.get("action")
        unique = canonical(read_changes(request.get("changes")))
        applied = check_references(unique, read_applied(request))
        order = topological_order(*dependents_graph(unique))
        if action == "rollback":
            # Read inside the same try as the graph work: ``invalid-retain``
            # ranks only below policy and graph codes, so a request that is
            # both cyclic and badly retained still reports the cycle.
            dependencies = {row["id"]: row["depends_on"] for row in unique}
            retain = _retain_set(request, applied, dependencies)
        else:
            retain = None
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = {row["id"]: row["units"] for row in unique}
    if action == "rollback":
        return _rollback(order, applied, units, retain)
    return _plan(order, applied, units, budget)


def _plan(order, applied, units, budget):
    """Emit unapplied changes in deterministic order if their total fits the budget.

    Already applied entries satisfy dependencies and are filtered out before
    accounting, so they never consume new budget. The budget is compared
    against the *emitted* sum after replay/deduplication and before anything
    is built, hence an excess emits no partial actions.
    """
    actions = [change_id for change_id in order if change_id not in applied]
    total = sum(units[change_id] for change_id in actions)
    if total > budget:
        return failure("budget-exceeded")
    return _emit(actions, total)


def _rollback(order, applied, units, retain):
    """Emit applied changes in reverse of the full deterministic topological order.

    Reverse order guarantees a dependent is rolled back before its
    prerequisite. The budget was already validated by policy but deliberately
    does not cap rollback, because undoing an already released journal must
    not be blocked by a planning quota.

    ``retain`` is dropped from the emitted list but never reorders it: retained
    IDs and their applied prerequisites simply skip, and every other applied ID
    keeps its position in the original deterministic reverse order. ``units``
    therefore sums only the IDs actually emitted (CHANGE-G2.md item 3).
    """
    actions = [change_id for change_id in reversed(order) if change_id in applied and change_id not in retain]
    return _emit(actions, sum(units[change_id] for change_id in actions))


def plan(request):
    """Entry point used by release.py; kept as the module's public name."""
    return handle(request)

