"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_request
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(changes):
    """Deterministic topological order with lexicographic tie-breaking.

    A change becomes eligible only once every dependency has been placed.
    The ID is the heap priority, so among all currently eligible changes the
    lexicographically smallest one is emitted next. Returns ``None`` when a
    cycle leaves some change permanently ineligible.
    """
    pending = {row["id"]: len(row["depends_on"]) for row in changes}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            dependents[dependency].append(row["id"])
    ready = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(pending):
        return None
    return order


def _result(order, by_id):
    units = 0
    for change_id in order:
        units += by_id[change_id]["units"]
    return {"status": "ok", "actions": list(order), "units": units}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        _environment, action, budget = limit_for(request)
        replay = read_request(request)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    by_id = replay["by_id"]
    # Full order over all changes; already applied entries satisfy
    # dependencies and take no new budget.
    order = _topological_order(replay["changes"])
    if order is None:
        return failure("dependency-cycle")
    if action == "rollback":
        # Budget is validated but does not cap rollback. Emit every applied
        # change, newest-first in the full deterministic topological order.
        emitted = [change_id for change_id in reversed(order) if change_id in replay["applied"]]
        return _result(emitted, by_id)
    emitted = [change_id for change_id in order if change_id not in replay["applied"]]
    if sum(by_id[change_id]["units"] for change_id in emitted) > budget:
        return failure("budget-exceeded")
    return _result(emitted, by_id)

