        if not isinstance(item, str) or not item or item in seen:
            return False
        seen.add(item)
    return True


def read_changes(records):
    """Validate change records and collapse identical duplicates.

    Returns a list of canonical dicts in first-seen order. Each dict holds
    ``id``, ``component``, ``units`` and sorted ``depends_on``. A repeated ID
    whose records differ in component, units or dependency set is rejected.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        change_id = row.get("id")
        component = row.get("component")
        units = row.get("units")
        depends_on = row.get("depends_on", [])
        if (not isinstance(change_id, str) or not change_id
                or not isinstance(component, str) or not component
                or type(units) is not int or units < 1
                or not _is_id_list(depends_on)):
            raise JournalError("invalid-change")
        change = {
            "id": change_id,
            "component": component,
            "units": units,
            "depends_on": sorted(depends_on),
        }
        previous = changes.get(change_id)
        if previous is None:
            changes[change_id] = change
        elif previous != change:
            raise JournalError("conflicting-change")
    return list(changes.values())


def read_applied(applied):
    """Validate the persisted release journal and return a set of IDs."""
    if not _is_id_list(applied):
        raise JournalError("invalid-change")
    return set(applied)


def read_retain(retain):
    """Validate a ``retain`` list and return its IDs.

    ``retain`` defaults to empty and must list distinct nonempty change IDs.
    Whether an ID is already applied is a property of the journal, so that
    check happens in ``read_request``.
    """
    if not _is_id_list(retain):
        raise JournalError("invalid-retain")
    return set(retain)


def read_request(request):
    """Normalize one request into a replay view.

    Raises ``JournalError`` for malformed input, conflicting IDs, references
    to unknown IDs and dependency cycles. All integrity checks run before any
    accounting so a rejected request never yields partial actions.

    ``retain`` only applies to rollback: it is parsed and validated there,
    and ignored for every other action. Its shape is checked with the other
    record shapes, before graph integrity; whether a retained ID is applied
    can only be judged once the applied set is trusted, so it comes after.
    """
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied", []))
    by_id = {row["id"]: row for row in changes}
    is_rollback = request.get("action") == "rollback"
    retain = read_retain(request.get("retain", [])) if is_rollback else set()
    for row in changes:
        for dependency in row["depends_on"]:
            if dependency not in by_id:
                raise JournalError("unknown-dependency")
    for change_id in applied:
        if change_id not in by_id:
            raise JournalError("unknown-dependency")
    if is_rollback and not retain <= applied:
        raise JournalError("invalid-retain")
    return {"changes": changes, "applied": applied, "retain": retain, "by_id": by_id}

