"""Compose policy and journal data into a plan.

Import direction (SPEC.md:3): planner.py imports journal.py and policy.py and is
imported only by release.py. Graph construction, deterministic order and result
assembly live here.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, check_budget, read_policy


# Failure objects are the exact five-key error shape (SPEC.md:7). A disallowed
# operation must emit no partial actions, so every check returns before
# `actions` is built and the empty list is the only one ever produced here.
def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _order(changes):
    """Return the full deterministic topological order of change IDs.

    Missing dependency targets fail with `unknown-dependency` and a cycle
    anywhere fails with `dependency-cycle` (SPEC.md:12); a cycle is detected even
    when it sits entirely in already-applied changes, because the caller's
    ledger would otherwise describe an impossible history. Eligible nodes are
    drained through a min-heap so ties break lexicographically by ID while
    ignoring input order (SPEC.md:13), which makes plan and rollback agree on one
    order. Kahn's algorithm dissolves exactly len(changes) nodes only when the
    graph is acyclic, so a shortfall is the cycle test.
    """
    known = {change["id"] for change in changes}
    remaining = {}
    dependents = {}
    for change in changes:
        for dependency in change["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
        remaining[change["id"]] = len(change["depends_on"])
        dependents.setdefault(change["id"], [])
    for change in changes:
        for dependency in change["depends_on"]:
            dependents[dependency].append(change["id"])
    ready = [change_id for change_id, pending in remaining.items() if pending == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    """Validate, order, then replay-filter the request into one result object."""
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = read_policy(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request, changes)
        order = _order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_of = {change["id"]: change["units"] for change in changes}
    applied_ids = set(applied)
    if action == "plan":
        # Already-applied entries satisfy dependencies (the graph above is the
        # full one) but emit nothing and consume no budget (SPEC.md:13).
        emitted = [change_id for change_id in order if change_id not in applied_ids]
    else:
        # Rollback reverses the full order so an applied entry always precedes
        # the prerequisites it needs; only applied entries are emitted, because
        # the others were never released and revoking them has no meaning.
        emitted = [change_id for change_id in reversed(order) if change_id in applied_ids]
    units = sum(units_of[change_id] for change_id in emitted)
    # Budget is checked on the emitted sum after replay/deduplication, and only
    # `plan` is capped (SPEC.md:13-14).
    if not check_budget(action, budget, units):
        return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted, "units": units}

